contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    // - depositAmount: amount of wei to send to Deposit
    // - logAddr: address to set as LogFile before initialization
    function run(uint depositAmount, address logAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        // ensure this test contract has Ether to send for Deposit
        require(address(this).balance >= depositAmount);

        // initialize c (must set MinSum or Log before Initialized; use zero MinSum)
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // read snapshots before Deposit
        uint recordedBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalBefore = address(c).balance;

        // attempt Deposit and record whether it reverted
        bool reverted;
        c.Deposit{value: depositAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after-values
        uint recordedAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint contractBalAfter = address(c).balance;

        // General rule:
        // - If Deposit succeeded then recordedAfter == recordedBefore + depositAmount
        //   and contractBalAfter == contractBalBefore + depositAmount.
        // - If Deposit reverted then recordedAfter == recordedBefore and contractBalAfter == contractBalBefore.
        assert(
            (!reverted)
            ? (recordedAfter == recordedBefore + depositAmount && contractBalAfter == contractBalBefore + depositAmount)
            : (recordedAfter == recordedBefore && contractBalAfter == contractBalBefore)
        );
    }

    // receive to accept refunds if c sends Ether back (not used here but safe)
    receive() external payable {}
}

